import{z as t,x as n,o as A,c as i,q as e,j as r,D as a,d as o,s as l,S as s}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"棋牌与棋类的教训","description":"","frontmatter":{"title":"棋牌与棋类的教训","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sgt-chess-poker-lessons.md","filePath":"llm/sgt-chess-poker-lessons.md","lastUpdated":1791413859000}'),p={name:"llm/sgt-chess-poker-lessons.md"};function d(h,E,F,D,m,C){const B=n("Mermaid");return A(),i("div",null,[E[2]||(E[2]=e('<h1 id="棋牌与棋类的教训" tabindex="-1">棋牌与棋类的教训 <a class="header-anchor" href="#棋牌与棋类的教训" aria-label="Permalink to &quot;棋牌与棋类的教训&quot;">​</a></h1><div class="epigraph"><p>自博弈在棋与牌上各自封神，但两顶王冠是两种方法赢来的：棋赢在「我可以假设对手就是我」，牌赢在「我承认对手不是」。</p><footer>—— 据 Silver et al., 2016/2017；Bowling et al., 2015；Moravčík et al., 2017；Brown &amp; Sandholm, 2018/2019 整理</footer></div><p><a href="/llm/sgt-nontransitivity">上一课</a>解释了对手课程为什么永远做不完：策略空间带环，有限采样必有盲区。本课回头读一部成功史——自博弈在完美信息的棋（国际象棋、围棋）与不完美信息的牌（德州扑克）上达到超人类水平——并提炼每条经验对语言模型的适用条件。教训不是「自博弈有效」，而是「自博弈在哪些条件下有效」；下一课的奖励塑形会用到其中最硬的一条：胜负判据必须先于策略存在。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自博弈的第一次系统胜利早于深度学习：Samuel 1959 的跳棋程序与自己对弈改进，Tesauro 1995 的 TD-Gammon 靠时序差分自博弈达到西洋双陆棋人类水平。当代的两个范式则把条件差异摆上台面。围棋侧：AlphaGo（Silver 等 2016）先模仿人类棋谱再自博弈超越；AlphaGo Zero（Silver 等 2017）从随机初始化、不用任何人类棋谱，纯自博弈加 MCTS 自蒸馏，三天超过战胜李世乭的版本，四十天定稿。扑克侧：不完美信息下最优策略依赖对手的真实范围，「对手即我」不能直接用，于是换引擎：CFR（Zinkevich 等 2007）用遗憾最小化逼近均衡，Cepheus 解决限注（Bowling 等 2015），DeepStack 与 Libratus 靠对当前策略反复求最佳响应拿下无限注（Moravčík 等 2017；Brown 与 Sandholm 2018），Pluribus 靠对平衡蓝本做局部搜索拿下六人局（Brown 与 Sandholm 2019）。</p><p><span class="marginnote">术语翻译：CFR（反事实遗憾最小化）就是「每一步都记着『当初要是出另一张牌会多赚多少』，再朝后悔最小的方向不断微调出牌概率」的手段——它直接逼近一个随机化的均衡策略，而不是训练一个确定性高手。Cepheus 用它解决了限注德州扑克。</span></p><p>两边的方法分工由<strong>信息结构</strong>决定：完美信息零和里对手无私有信息，假设「对手是我」几乎无损，纯自博弈可以从零爬到神；不完美信息里均衡是混合策略，纯自博弈会暴露自身规律，目标必须从「赢下这局」退化成「不可被打穿」。</p><p><span class="marginnote">常见误区：初学者容易把 AlphaGo Zero 和 Libratus 当成「同一种自博弈」的强弱两版，实际上两者的目标都不同：Zero 优化的是胜率（赢下这一局），扑克 AI 优化的是不可剥削度（不被打穿）。把前者的配方搬到扑克上，会得到一个能被针对性打爆的「高手」。</span></p><h3 id="教训清单" tabindex="-1">教训清单 <a class="header-anchor" href="#教训清单" aria-label="Permalink to &quot;教训清单&quot;">​</a></h3><p>四条直接可搬。其一，<strong>环境可模拟</strong>：棋与牌都能在闭环里以极低成本采样对局，自博弈的数据引擎是模拟器；语言任务缺少等价物，「对话模拟器」本身就是另一个模型。其二，<strong>胜负判据外生且廉价</strong>：将死、筹码清零，判据不随训练漂移；语言任务的「赢」要靠评测或奖励模型，判据自己会博弈（下一课与<a href="/llm/reward-hacking-llm">奖励黑客</a>的主题）。其三，<strong>对手假设要与信息结构匹配</strong>：完美信息可以「对手即我」，不完美信息必须以可利用度为目标、用均衡求解或防御式自博弈。其四，<strong>多人与合作是断崖</strong>：Hanabi 作为合作不完全信息博弈成为新基准（Bard 等 2020），其难点是约定与信念而非计算——这预告了语言模型自博弈的真正难度：那里几乎全是 Hanabi 式问题。</p><p><span class="marginnote">AlphaGo Zero 与扑克 AI 的对照一句话：Zero 不需要人类数据因为它可以定义「更好」（胜率），扑克 AI 不敢只用胜率因为它要定义「不可剥削」。语言模型两边都不占：既无外生胜率，也无可算的可利用度。</span></p>',11)),(A(),r(s,null,{default:a(()=>[l(B,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENV%5B%22%E5%AF%B9%E5%BC%88%E7%8E%AF%E5%A2%83%22%5D%20--%3E%20PI%5B%22%E5%AE%8C%E7%BE%8E%E4%BF%A1%E6%81%AF%EF%BC%9A%E5%9B%B4%E6%A3%8B%E3%80%81%E5%9B%BD%E9%99%85%E8%B1%A1%E6%A3%8B%22%5D%0A%20%20ENV%20--%3E%20II%5B%22%E4%B8%8D%E5%AE%8C%E7%BE%8E%E4%BF%A1%E6%81%AF%EF%BC%9A%E6%89%91%E5%85%8B%E3%80%81Hanabi%22%5D%0A%20%20PI%20--%3E%20SP%5B%22%E7%BA%AF%E8%87%AA%E5%8D%9A%E5%BC%88%E5%8F%AF%E8%A1%8C%EF%BC%9A%E5%AF%B9%E6%89%8B%E5%8D%B3%E6%88%91%22%5D%0A%20%20SP%20--%3E%20AGZ%5B%22AlphaGo%20Zero%EF%BC%9A%E9%9A%8F%E6%9C%BA%E8%B5%B7%E3%80%81%E5%9B%9B%E5%8D%81%E5%A4%A9%E5%B0%81%E7%A5%9E%22%5D%0A%20%20II%20--%3E%20EQG%5B%22%E7%9B%AE%E6%A0%87%E6%8D%A2%E6%88%90%E4%B8%8D%E5%8F%AF%E5%89%A5%E5%89%8A%EF%BC%9ACFR%2F%E5%93%8D%E5%BA%94%E6%90%9C%E7%B4%A2%22%5D%0A%20%20EQG%20--%3E%20LIB%5B%22%E9%99%90%E6%B3%A8%E8%A2%AB%E8%A7%A3%E3%80%81%E6%97%A0%E9%99%90%E6%B3%A8%E8%B6%85%E4%BA%BA%E7%B1%BB%22%5D%0A%20%20AGZ%20--%3E%20LES%5B%22%E5%9B%9B%E6%9D%A1%E6%95%99%E8%AE%AD%EF%BC%9A%E6%A8%A1%E6%8B%9F%E5%99%A8%E3%80%81%E5%A4%96%E7%94%9F%E8%83%9C%E8%B4%9F%E3%80%81%E5%AF%B9%E6%89%8B%E5%81%87%E8%AE%BE%E3%80%81%E5%90%88%E4%BD%9C%E6%96%AD%E5%B4%96%22%5D%0A%20%20LIB%20--%3E%20LES%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[o(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>本课的方法是<strong>条件对照的历史分析</strong>：不把 AlphaGo Zero 与扑克 AI 当作并列的成功案例，而是按信息结构分成完美与不完美两极，逐案核对各自依赖的前提——可模拟的环境、外生胜负判据、与信息结构匹配的对手假设——把前提提炼成四条可搬运的清单。两极恰好构成「对手即我」与「不可剥削」两种方法论的对照实验，单看任何一半都会把条件误读成风格。语言模型侧的处理方式是把清单当核对表用：逐项比对，而不是从「自博弈有效」直接外推。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么「对手即我」在围棋成立、在扑克不成立？完美信息零和里双方共享同一状态、效用严格相反，均衡恰好是自博弈的不动点，这个假设无偏；不完美信息引入私有信息后，「我若这样想对手也会这样想」的二阶推理不再自洽——均衡要求随机化，确定性的追逐必然暴露。CFR 的机制是用遗憾和逼近这个混合，而不是让两个确定性策略互相追：自博弈没有消失，它退到「对自身混合的期望」这层。</p><p><span class="marginnote">直觉类比：完美信息像下明棋，双方看同一张棋盘，「假设对面就是我」几乎不亏；不完美信息像打牌，你手里有对方看不见的底牌——若出牌规律是确定的，对手摸几局就能反推出你的习惯。所以均衡策略必须「掷骰子」式地随机化，这正是 CFR 在学的东西。</span></p><p>把同一张核对表放到三方上，语言模型自博弈的位置就清楚了：</p>',6)),(A(),r(s,null,{default:a(()=>[l(B,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20GO%5B%22%E5%9B%B4%E6%A3%8B%22%5D%20--%3E%20G1%5B%22%E7%8E%AF%E5%A2%83%E5%8F%AF%E6%A8%A1%E6%8B%9F%3A%20%E6%98%AF%2C%20%E5%88%A4%E6%8D%AE%E5%A4%96%E7%94%9F%22%5D%0A%20%20GO%20--%3E%20G2%5B%22%E5%AF%B9%E6%89%8B%E5%8D%B3%E6%88%91%E6%88%90%E7%AB%8B%2C%20%E7%BA%AF%E8%87%AA%E5%8D%9A%E5%BC%88%E5%B0%81%E7%A5%9E%22%5D%0A%20%20PK%5B%22%E6%89%91%E5%85%8B%22%5D%20--%3E%20P1%5B%22%E7%8E%AF%E5%A2%83%E5%8F%AF%E6%A8%A1%E6%8B%9F%3A%20%E6%98%AF%22%5D%0A%20%20PK%20--%3E%20P2%5B%22%E7%9B%AE%E6%A0%87%E6%8D%A2%E6%88%90%E4%B8%8D%E5%8F%AF%E5%89%A5%E5%89%8A%3A%20CFR%20%2F%20%E5%93%8D%E5%BA%94%E6%90%9C%E7%B4%A2%22%5D%0A%20%20LM%5B%22%E8%AF%AD%E8%A8%80%E6%A8%A1%E5%9E%8B%E8%87%AA%E5%8D%9A%E5%BC%88%22%5D%20--%3E%20L1%5B%22%E6%A8%A1%E6%8B%9F%E5%99%A8%E4%B8%8E%E5%88%A4%E6%8D%AE%E9%83%BD%E6%98%AF%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20LM%20--%3E%20L2%5B%22%E6%9D%A1%E4%BB%B6%E6%9C%80%E6%8E%A5%E8%BF%91%20Hanabi%20%E8%80%8C%E9%9D%9E%E5%9B%B4%E6%A3%8B%22%5D%0A%20%20G2%20--%3E%20SUM%5B%22%E5%AF%B9%E6%89%8B%E5%81%87%E8%AE%BE%E5%BF%85%E9%A1%BB%E4%B8%8E%E4%BF%A1%E6%81%AF%E7%BB%93%E6%9E%84%E5%8C%B9%E9%85%8D%22%5D%0A%20%20P2%20--%3E%20SUM%0A%20%20L2%20--%3E%20SUM%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[o(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p>语言模型自博弈在机制表上的位置很尴尬：对话是不完美信息（用户意图不可见）、一般和（不必你输我赢）、且模拟器与被判据都由模型充任。按本课清单，它的可行域最接近 Hanabi 而不是围棋：先把约定与信念搞对，再谈强度。这解释了后课为什么要给自博弈配塑形、辩论与协商，而不是直接开两个模型对打。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课教训的适用边界在「环境」上：棋牌环境是真规则系统，「可模拟、判据外生」是环境的属性；语言任务的环境本身是模型的产物，教训只能以类比方式借用。多人零和（Pluribus）的成功还依赖「多数对手近似均衡」的假设，语言场景的对手分布离它更远。把教训读成「自博弈万能」或「只对棋有效」都错：正确的读法是逐条件核对，缺哪条补哪条——补模拟器、补判据、补对手假设，分别通向塑形课、评测课与机制课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>棋与牌的胜利方法不同：完美信息用纯自博弈（对手即我），不完美信息以可利用度为目标（CFR、响应搜索）。</li><li>教训四条：可模拟的环境、外生的胜负判据、与信息结构匹配的对手假设、多人合作是断崖。</li><li>AlphaGo Zero 证明无人类数据的自博弈上限，但其前提是外生胜率；扑克 AI 证明防御式自博弈上限，前提是可算均衡近似。</li><li>语言模型自博弈的条件结构最近 Hanabi 而非围棋：不完美信息加一般和加自充判据。</li><li>教训是逐条件核对，缺哪条补哪条，不做「有效/无效」的二值外推。</li><li>出处：Silver 等 2016/2017；Zinkevich 等 2007；Bowling 等 2015；Moravčík 等 2017；Brown 与 Sandholm 2018/2019；Bard 等 2020。</li></ul>',5))])}const u=t(p,[["render",d]]);export{c as __pageData,u as default};
